-- Seed: Training visuals round 2 — 22 new SVG visual lessons across all 14 courses
-- Run AFTER 021_training_academy.sql in the WorkTeams Supabase project.
-- Idempotent: each lesson is deleted by exact title before insert; safe to re-run.

-- sales-training: The lead intake sheet: what to capture before the walkthrough
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'sales-training') and kind = 'visual' and title = 'The lead intake sheet: what to capture before the walkthrough';
with c as (select id as cid from public.training_courses where slug = 'sales-training'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'The lead intake sheet: what to capture before the walkthrough',
'Never walk into a building cold. Before the walkthrough is even booked, capture the facts on one intake sheet: who decides, what they have now, and what bothers them most. That last answer tells you exactly what to look at first on the tour — and what to promise in the bid. If they will not agree to a walkthrough, they are not a real prospect yet.',
'<svg width="460" height="470" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="460" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">LEAD INTAKE SHEET</text><text x="40" y="67" font-size="12" fill="#475569">Prospect name</text><rect x="40" y="74" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="92" font-size="12" fill="#94a3b8">Maria Santos</text><text x="40" y="107" font-size="12" fill="#475569">Company</text><rect x="40" y="114" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="132" font-size="12" fill="#94a3b8">Santos Insurance LLC</text><text x="40" y="147" font-size="12" fill="#475569">Phone / email</text><rect x="40" y="154" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="172" font-size="12" fill="#94a3b8">(555) 014-2288</text><text x="40" y="187" font-size="12" fill="#475569">Building address</text><rect x="40" y="194" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="212" font-size="12" fill="#94a3b8">410 Main St, Suite 200</text><text x="40" y="227" font-size="12" fill="#475569">Approx. sq ft</text><rect x="40" y="234" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="252" font-size="12" fill="#94a3b8">about 2,500</text><text x="40" y="267" font-size="12" fill="#475569">Current cleaner</text><rect x="40" y="274" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="292" font-size="12" fill="#94a3b8">ABC Janitorial</text><text x="40" y="307" font-size="12" fill="#475569">What bothers you most?</text><rect x="40" y="314" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="332" font-size="12" fill="#94a3b8">Restrooms never feel clean</text><text x="40" y="347" font-size="12" fill="#475569">Decision maker?</text><rect x="40" y="354" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="372" font-size="12" fill="#94a3b8">Yes — Maria decides</text><text x="40" y="387" font-size="12" fill="#475569">Walkthrough agreed</text><rect x="40" y="394" width="380" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="48" y="412" font-size="12" fill="#94a3b8">Tue 10:00 AM</text></svg>';

-- sales-training: The measurement screen: entering rooms in the app
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'sales-training') and kind = 'visual' and title = 'The measurement screen: entering rooms in the app';
with c as (select id as cid from public.training_courses where slug = 'sales-training'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 4, 'visual', 'The measurement screen: entering rooms in the app',
'On the walkthrough you type each room straight into the app: name it, enter length and width, pick the floor type. The app does the math — 20 times 15 is 300 square feet — and keeps a running total as you add rooms. No notepad math, no lost numbers, nothing to retype back at the office.',
'<svg width="460" height="400" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="390" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">MEASURING IN THE APP</text><rect x="130" y="48" width="200" height="330" rx="18" fill="#ffffff" stroke="#0f172a" stroke-width="2"/><rect x="130" y="48" width="200" height="34" rx="17" fill="#0f172a"/><rect x="130" y="65" width="200" height="17" fill="#0f172a"/><text x="230.0" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">New room</text><text x="146" y="107" font-size="12" fill="#475569">Room name</text><rect x="146" y="114" width="168" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="154" y="132" font-size="12" fill="#94a3b8">Lobby</text><text x="146" y="155" font-size="12" fill="#475569">Length (ft)</text><rect x="146" y="162" width="76" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="154" y="180" font-size="12" fill="#94a3b8">20</text><text x="238" y="155" font-size="12" fill="#475569">Width (ft)</text><rect x="238" y="162" width="76" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="246" y="180" font-size="12" fill="#94a3b8">15</text><text x="146" y="203" font-size="12" fill="#475569">Floor type</text><rect x="146" y="210" width="168" height="26" rx="6" fill="#ffffff" stroke="#cbd5e1"/><text x="154" y="228" font-size="12" fill="#94a3b8">Tile  ▾</text><rect x="146" y="252" width="168" height="34" rx="8" fill="#dbeafe" stroke="#2563eb"/><text x="230" y="274" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e3a8a">300 sq ft</text><rect x="146" y="296" width="168" height="34" rx="8" fill="#2563eb"/><text x="230" y="318" text-anchor="middle" font-size="14" font-weight="bold" fill="#ffffff">+ Add room</text><text x="230" y="360" text-anchor="middle" font-size="12" fill="#475569">3 rooms so far · 1,150 sq ft</text></svg>';

-- sales-training: The scope checklist: tapping off each room's tasks
