l="#cbd5e1"></text><text x="158" y="222" font-size="12" fill="#0f172a">Clean glass entry doors</text><rect x="124" y="238" width="212" height="30" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="132" y="244" width="18" height="18" rx="5" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/><text x="141" y="258" text-anchor="middle" font-size="13" font-weight="bold" fill="#cbd5e1"></text><text x="158" y="258" font-size="12" fill="#0f172a">Spot-clean walls</text><text x="230" y="360" text-anchor="middle" font-size="12" fill="#475569">2 of 5 tapped · building: 14 of 34</text></svg>';

