'<svg width="460" height="372" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="362" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">BUILDING TOTALS</text><text x="60" y="100" font-size="13" fill="#0f172a">Lobby</text><text x="400" y="100" text-anchor="end" font-size="13" fill="#0f172a">300 sq ft</text><line x1="40" y1="112" x2="420" y2="112" stroke="#e2e8f0"/><text x="60" y="132" font-size="13" fill="#0f172a">Open office</text><text x="400" y="132" text-anchor="end" font-size="13" fill="#0f172a">1,200 sq ft</text><line x1="40" y1="144" x2="420" y2="144" stroke="#e2e8f0"/><text x="60" y="164" font-size="13" fill="#0f172a">2 private offices</text><text x="400" y="164" text-anchor="end" font-size="13" fill="#0f172a">300 sq ft</text><line x1="40" y1="176" x2="420" y2="176" stroke="#e2e8f0"/><text x="60" y="196" font-size="13" fill="#0f172a">Restroom</text><text x="400" y="196" text-anchor="end" font-size="13" fill="#0f172a">200 sq ft</text><line x1="40" y1="208" x2="420" y2="208" stroke="#e2e8f0"/><text x="60" y="228" font-size="13" fill="#0f172a">Break room</text><text x="400" y="228" text-anchor="end" font-size="13" fill="#0f172a">200 sq ft</text><line x1="40" y1="240" x2="420" y2="240" stroke="#e2e8f0"/><text x="60" y="260" font-size="13" fill="#0f172a">Hallways</text><text x="400" y="260" text-anchor="end" font-size="13" fill="#0f172a">250 sq ft</text><rect x="40" y="292" width="380" height="36" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="60" y="315" font-size="14" font-weight="bold" fill="#14532d">BUILDING TOTAL</text><text x="400" y="315" text-anchor="end" font-size="14" font-weight="bold" fill="#14532d">2,450 sq ft</text><text x="230" y="352" text-anchor="middle" font-size="12" fill="#475569">34 scope tasks across 6 areas</text></svg>';

-- sales-training: Pricing modes: pick the right one with a tap
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'sales-training') and kind = 'visual' and title = 'Pricing modes: pick the right one with a tap';
with c as (select id as cid from public.training_courses where slug = 'sales-training'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 7, 'visual', 'Pricing modes: pick the right one with a tap',
'Three ways to price, one tap to switch. Per hour for small or irregular jobs. Per square foot for regular commercial work — the totals sheet feeds straight into it. Flat rate for residential and one-time jobs. Pick the mode that fits the job; the math updates itself.',
'<svg width="460" height="392" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="382" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">PRICING MODES</text><rect x="40" y="52" width="380" height="96" rx="10" fill="#dbeafe" stroke="#1e3a8a"/><circle cx="66" cy="80" r="12" fill="#ffffff" stroke="#1e3a8a" stroke-width="2"/><circle cx="66" cy="80" r="5" fill="#1e3a8a"/><text x="88" y="85" font-size="15" font-weight="bold" fill="#1e3a8a">PER HOUR</text><text x="60" y="110" font-size="13" fill="#1e3a8a">$45/hr per cleaner</text><text x="60" y="132" font-size="12" fill="#1e3a8a">Best for: Small or irregular jobs</text><rect x="40" y="160" width="380" height="96" rx="10" fill="#dcfce7" stroke="#14532d"/><circle cx="66" cy="188" r="12" fill="#ffffff" stroke="#14532d" stroke-width="2"/><circle cx="66" cy="188" r="5" fill="#14532d"/><text x="88" y="193" font-size="15" font-weight="bold" fill="#14532d">PER SQ FT</text><text x="60" y="218" font-size="13" fill="#14532d">$0.12 / sq ft / visit</text><text x="60" y="240" font-size="12" fill="#14532d">Best for: Regular commercial cleans</text><rect x="40" y="268" width="380" height="96" rx="10" fill="#fef9c3" stroke="#713f12"/><circle cx="66" cy="296" r="12" fill="#ffffff" stroke="#713f12" stroke-width="2"/><circle cx="66" cy="296" r="5" fill="#713f12"/><text x="88" y="301" font-size="15" font-weight="bold" fill="#713f12">FLAT RATE</text><text x="60" y="326" font-size="13" fill="#713f12">$850 / month</text><text x="60" y="348" font-size="12" fill="#713f12">Best for: Residential &amp; one-time jobs</text></svg>';

-- sales-training: The finished contract: what 'done' looks like
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'sales-training') and kind = 'visual' and title = 'The finished contract: what ''done'' looks like';
with c as (select id as cid from public.training_courses where slug = 'sales-training'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 8, 'visual', 'The finished contract: what ''done'' looks like',
'A finished contract has five parts and no surprises: who the parties are, the scope attached from the walkthrough, the price and billing day, the term and cancel notice, and two signatures. Send it for e-signature the same day you present the bid — momentum closes deals.',
'<svg width="460" height="448" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="438" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">FINISHED SALES CONTRACT</text><rect x="90" y="48" width="280" height="380" rx="6" fill="#ffffff" stroke="#94a3b8"/><text x="230" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SERVICE AGREEMENT</text><line x1="110" y1="90" x2="350" y2="90" stroke="#e2e8f0"/><text x="110" y="112" font-size="12" font-weight="bold" fill="#2563eb">1. PARTIES</text><text x="110" y="130" font-size="11" fill="#475569">Your company + client name and address</text><text x="110" y="156" font-size="12" font-weight="bold" fill="#2563eb">2. SCOPE (attached)</text><text x="110" y="174" font-size="11" fill="#475569">Room-by-room task list from the walkthrough</text><text x="110" y="200" font-size="12" font-weight="bold" fill="#2563eb">3. PRICE</text><text x="110" y="218" font-size="11" fill="#475569">$850/month · billed 1st of month</text><text x="110" y="244" font-size="12" font-weight="bold" fill="#2563eb">4. TERM</text><text x="110" y="262" font-size="11" fill="#475569">12 months · 30-day cancel notice</text><text x="110" y="288" font-size="12" font-weight="bold" fill="#2563eb">5. SIGNATURES</text><line x1="110" y1="330" x2="220" y2="330" stroke="#0f172a"/><line x1="240" y1="330" x2="350" y2="330" stroke="#0f172a"/><text x="110" y="344" font-size="10" fill="#94a3b8">You</text><text x="240" y="344" font-size="10" fill="#94a3b8">Client</text><rect x="110" y="366" width="240" height="34" rx="8" fill="#16a34a"/><text x="230" y="388" text-anchor="middle" font-size="13" font-weight="bold" fill="#ffffff">Send for e-signature</text></svg>';

-- accounting-training: Anatomy of an invoice: the six things every invoice needs
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'accounting-training') and kind = 'visual' and title = 'Anatomy of an invoice: the six things every invoice needs';
with c as (select id as cid from public.training_courses where slug = 'accounting-training'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'Anatomy of an invoice: the six things every invoice needs',
'Every invoice you send needs the same six things: your business info, an invoice number and date, who it bills, line items showing what the money is for, a big clear total, and when and how to pay. Miss one and the invoice bounces back — and your cash waits.',
'<svg width="460" height="428" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="418" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">INVOICE ANATOMY</text><rect x="80" y="48" width="300" height="360" rx="6" fill="#ffffff" stroke="#94a3b8"/><text x="230" y="74" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">INVOICE #1042</text><line x1="100" y1="88" x2="360" y2="88" stroke="#e2e8f0"/><circle cx="392" cy="100" r="11" fill="#2563eb"/><text x="392" y="104" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">1</text><text x="386" y="104" text-anchor="end" font-size="10" fill="#1e3a8a">Your logo + business info</text><circle cx="392" cy="128" r="11" fill="#2563eb"/><text x="392" y="132" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">2</text><text x="386" y="132" text-anchor="end" font-size="10" fill="#1e3a8a">Invoice number + date</text><circle cx="392" cy="156" r="11" fill="#2563eb"/><text x="392" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">3</text><text x="386" y="160" text-anchor="end" font-size="10" fill="#1e3a8a">Bill-to: client name</text><circle cx="68" cy="192" r="11" fill="#2563eb"/><text x="68" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">4</text><text x="84" y="196" font-size="10" fill="#1e3a8a">Line items: what + how much</text><circle cx="68" cy="264" r="11" fill="#2563eb"/><text x="68" y="268" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">5</text><text x="84" y="268" font-size="10" fill="#1e3a8a">Total due (big and clear)</text><circle cx="68" cy="292" r="11" fill="#2563eb"/><text x="68" y="296" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">6</text><text x="84" y="296" font-size="10" fill="#1e3a8a">Due date + pay-by info</text><text x="100" y="104" font-size="11" fill="#475569">Lilly B’s Janitorial</text><text x="100" y="132" font-size="11" fill="#475569">#1042 · Oct 1, 2026</text><text x="100" y="160" font-size="11" fill="#475569">Santos Insurance LLC</text><text x="100" y="196" font-size="11" fill="#475569">Weekly cleaning × 4 ......... $850.00</text><text x="100" y="268" font-size="13" font-weight="bold" fill="#0f172a">TOTAL DUE: $850.00</text><text x="100" y="296" font-size="11" fill="#475569">Due Oct 15 · ACH / check</text><text x="230" y="392" text-anchor="middle" font-size="11" fill="#475569">Missing any of the six? The invoice comes back.</text></svg>';

-- accounting-training: The cash cycle: from job done to money in the bank
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'accounting-training') and kind = 'visual' and title = 'The cash cycle: from job done to money in the bank';
with c as (select id as cid from public.training_courses where slug = 'accounting-training'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 4, 'visual', 'The cash cycle: from job done to money in the bank',
'Cash moves in a loop: the job gets done, the invoice goes out, payment comes in, bills and payroll go out, and it starts again. The loop breaks in one place most often — invoicing late. Invoice the day the job is done and the whole cycle speeds up.',
'<svg width="460" height="300" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="290" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">THE CASH CYCLE</text><rect x="28" y="120" width="96" height="80" rx="10" fill="#dbeafe" stroke="#1e3a8a"/><text x="76" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Job done</text><text x="76" y="172" text-anchor="middle" font-size="20" fill="#1e3a8a">1</text><polygon points="124,152 136,160 124,168" fill="#64748b"/><rect x="132" y="120" width="96" height="80" rx="10" fill="#e0f2fe" stroke="#0c4a6e"/><text x="180" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#0c4a6e">Invoice sent</text><text x="180" y="172" text-anchor="middle" font-size="20" fill="#0c4a6e">2</text><polygon points="228,152 240,160 228,168" fill="#64748b"/><rect x="236" y="120" width="96" height="80" rx="10" fill="#dcfce7" stroke="#14532d"/><text x="284" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Payment in</text><text x="284" y="172" text-anchor="middle" font-size="20" fill="#14532d">3</text><polygon points="332,152 344,160 332,168" fill="#64748b"/><rect x="340" y="120" width="96" height="80" rx="10" fill="#fef9c3" stroke="#713f12"/><text x="388" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">Bills + payroll</text><text x="388" y="172" text-anchor="middle" font-size="20" fill="#713f12">4</text><text x="230" y="70" text-anchor="middle" font-size="13" fill="#475569">Money has to make the full loop.</text><text x="230" y="250" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">Slow invoicing = slow cash. Invoice the day the job is done.</text><text x="230" y="272" text-anchor="middle" font-size="12" fill="#475569">Target: every invoice out within 24 hours.</text></svg>';

-- customer-service: The escalation ladder: what you handle vs. what goes up
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'customer-service') and kind = 'visual' and title = 'The escalation ladder: what you handle vs. what goes up';
with c as (select id as cid from public.training_courses where slug = 'customer-service'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'The escalation ladder: what you handle vs. what goes up',
'Not every problem is yours to solve — and not every problem should wait. Handle the small stuff on the spot: running late, a missed trash can. Kick restroom complaints to your lead, damage or an angry client to the manager, and anything legal, injury, or media straight to the owner. When in doubt, go one rung higher.',
'<svg width="460" height="428" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="418" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">ESCALATION LADDER</text><rect x="40" y="56" width="380" height="76" rx="10" fill="#dcfce7" stroke="#14532d"/><text x="230.0" y="84" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">YOU handle it</text><text x="230.0" y="108" text-anchor="middle" font-size="12" fill="#14532d">Running late · missed trash · quick question</text><rect x="60" y="144" width="340" height="76" rx="10" fill="#dbeafe" stroke="#1e3a8a"/><text x="230.0" y="172" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e3a8a">Your LEAD handles it</text><text x="230.0" y="196" text-anchor="middle" font-size="12" fill="#1e3a8a">Restroom complaint · streaky windows</text><rect x="80" y="232" width="300" height="76" rx="10" fill="#fef9c3" stroke="#713f12"/><text x="230.0" y="260" text-anchor="middle" font-size="14" font-weight="bold" fill="#713f12">MANAGER steps in</text><text x="230.0" y="284" text-anchor="middle" font-size="12" fill="#713f12">Damage · angry client · refund ask</text><rect x="100" y="320" width="260" height="76" rx="10" fill="#fee2e2" stroke="#7f1d1d"/><text x="230.0" y="348" text-anchor="middle" font-size="14" font-weight="bold" fill="#7f1d1d">OWNER only</text><text x="230.0" y="372" text-anchor="middle" font-size="12" fill="#7f1d1d">Legal threat · injury · media</text></svg>';

-- customer-service: The 5-minute service recovery: turn a complaint into loyalty
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'customer-service') and kind = 'visual' and title = 'The 5-minute service recovery: turn a complaint into loyalty';
with c as (select id as cid from public.training_courses where slug = 'customer-service'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 4, 'visual', 'The 5-minute service recovery: turn a complaint into loyalty',
'A complaining client who gets a fast, sincere fix becomes more loyal than one who never complained. Four moves, five minutes: listen all the way through, apologize like you mean it, fix it on the spot before they ask, and call tomorrow to confirm it is right. Write down what happened so it never repeats.',
'<svg width="460" height="412" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="402" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">5-MINUTE SERVICE RECOVERY</text><rect x="40" y="56" width="380" height="72" rx="10" fill="#dbeafe" stroke="#1e3a8a"/><text x="60" y="86" font-size="15" font-weight="bold" fill="#1e3a8a">1. LISTEN</text><text x="60" y="108" font-size="12" fill="#1e3a8a">Let them finish. Do not interrupt, do not argue.</text><rect x="40" y="140" width="380" height="72" rx="10" fill="#e0f2fe" stroke="#0c4a6e"/><text x="60" y="170" font-size="15" font-weight="bold" fill="#0c4a6e">2. APOLOGIZE</text><text x="60" y="192" font-size="12" fill="#0c4a6e">"You are right to be upset. I am sorry."</text><rect x="40" y="224" width="380" height="72" rx="10" fill="#fef9c3" stroke="#713f12"/><text x="60" y="254" font-size="15" font-weight="bold" fill="#713f12">3. FIX IT NOW</text><text x="60" y="276" font-size="12" fill="#713f12">Offer the fix before they ask for one.</text><rect x="40" y="308" width="380" height="72" rx="10" fill="#dcfce7" stroke="#14532d"/><text x="60" y="338" font-size="15" font-weight="bold" fill="#14532d">4. FOLLOW UP</text><text x="60" y="360" font-size="12" fill="#14532d">Call tomorrow: “Is it right now?”</text></svg>';

-- hr-management: New-hire timeline: day 1 to day 30
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'hr-management') and kind = 'visual' and title = 'New-hire timeline: day 1 to day 30';
with c as (select id as cid from public.training_courses where slug = 'hr-management'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'New-hire timeline: day 1 to day 30',
'Great cleaners are made in the first 30 days. Day 1 is paperwork, a tour, and shadowing — no solo work. Week 1 they shadow a lead every day. Day 14 is the first solo clean, and it gets checked. Day 30 is the sit-down review with a clear path to a raise. Rush this timeline and you re-hire the same seat in 60 days.',
'<svg width="460" height="312" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="302" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">NEW-HIRE TIMELINE</text><line x1="40" y1="150" x2="420" y2="150" stroke="#94a3b8" stroke-width="3"/><circle cx="80" cy="150" r="14" fill="#dbeafe" stroke="#1e3a8a" stroke-width="2"/><text x="80" y="155" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">1</text><rect x="40" y="180" width="80" height="70" rx="8" fill="#dbeafe" stroke="#1e3a8a"/><text x="80" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">DAY 1</text><text x="80" y="220" text-anchor="middle" font-size="9" fill="#1e3a8a">Paperwork + tour + shadow</text><circle cx="180" cy="150" r="14" fill="#e0f2fe" stroke="#0c4a6e" stroke-width="2"/><text x="180" y="155" text-anchor="middle" font-size="11" font-weight="bold" fill="#0c4a6e">2</text><rect x="140" y="180" width="80" height="70" rx="8" fill="#e0f2fe" stroke="#0c4a6e"/><text x="180" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#0c4a6e">WEEK 1</text><text x="180" y="220" text-anchor="middle" font-size="9" fill="#0c4a6e">Shadow a lead daily</text><circle cx="280" cy="150" r="14" fill="#fef9c3" stroke="#713f12" stroke-width="2"/><text x="280" y="155" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">3</text><rect x="240" y="180" width="80" height="70" rx="8" fill="#fef9c3" stroke="#713f12"/><text x="280" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">DAY 14</text><text x="280" y="220" text-anchor="middle" font-size="9" fill="#713f12">First solo clean — checked</text><circle cx="380" cy="150" r="14" fill="#dcfce7" stroke="#14532d" stroke-width="2"/><text x="380" y="155" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">4</text><rect x="340" y="180" width="80" height="70" rx="8" fill="#dcfce7" stroke="#14532d"/><text x="380" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">DAY 30</text><text x="380" y="220" text-anchor="middle" font-size="9" fill="#14532d">Review + raise path</text><text x="230" y="290" text-anchor="middle" font-size="12" fill="#475569">Nobody cleans solo before day 14. Ever.</text></svg>';

-- hr-management: The employee file: six papers that protect you
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'hr-management') and kind = 'visual' and title = 'The employee file: six papers that protect you';
with c as (select id as cid from public.training_courses where slug = 'hr-management'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 4, 'visual', 'The employee file: six papers that protect you',
'If it is not in the file, it did not happen. Every employee file holds six things: the signed application, I-9 eligibility, W-4 tax form, signed handbook acknowledgment, training certificates, and performance reviews. This file is what stands between you and a bad unemployment claim or a lawsuit.',
'<svg width="460" height="424" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="414" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">EMPLOYEE FILE CHECKLIST</text><rect x="150" y="52" width="160" height="44" rx="6" fill="#fbbf24" stroke="#b45309"/><text x="230" y="79" text-anchor="middle" font-size="13" font-weight="bold" fill="#451a03">EMPLOYEE FILE</text><rect x="60" y="108" width="340" height="36" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="72" y="117" width="18" height="18" rx="5" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="81" y="131" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">✓</text><text x="100" y="131" font-size="12" fill="#0f172a">Job application (signed)</text><rect x="60" y="154" width="340" height="36" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="72" y="163" width="18" height="18" rx="5" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="81" y="177" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">✓</text><text x="100" y="177" font-size="12" fill="#0f172a">I-9 employment eligibility</text><rect x="60" y="200" width="340" height="36" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="72" y="209" width="18" height="18" rx="5" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="81" y="223" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">✓</text><text x="100" y="223" font-size="12" fill="#0f172a">W-4 tax form</text><rect x="60" y="246" width="340" height="36" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="72" y="255" width="18" height="18" rx="5" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="81" y="269" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">✓</text><text x="100" y="269" font-size="12" fill="#0f172a">Handbook acknowledgment</text><rect x="60" y="292" width="340" height="36" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="72" y="301" width="18" height="18" rx="5" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="81" y="315" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">✓</text><text x="100" y="315" font-size="12" fill="#0f172a">Training certificates</text><rect x="60" y="338" width="340" height="36" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="72" y="347" width="18" height="18" rx="5" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="81" y="361" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">✓</text><text x="100" y="361" font-size="12" fill="#0f172a">Performance reviews</text><text x="230" y="404" text-anchor="middle" font-size="12" fill="#475569">No file, no defense. Keep every one current.</text></svg>';

-- operations-management: The dispatch board: the whole day at a glance
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'operations-management') and kind = 'visual' and title = 'The dispatch board: the whole day at a glance';
with c as (select id as cid from public.training_courses where slug = 'operations-management'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 2, 'visual', 'The dispatch board: the whole day at a glance',
'One screen shows every crew and every job in time order. You can see gaps, overloads, and drive-time problems before the day starts. A healthy day has no crew idle and no crew double-booked — if the board does not balance at 7 AM, fix it before the crews roll.',
'<svg width="460" height="372" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="362" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">DISPATCH BOARD</text><rect x="28" y="56" width="130" height="270" rx="10" fill="#ffffff" stroke="#94a3b8"/><text x="93" y="80" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Crew A — Rosa</text><rect x="36" y="96" width="114" height="60" rx="8" fill="#dbeafe" stroke="#cbd5e1"/><text x="93" y="120" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">8:00</text><text x="93" y="138" text-anchor="middle" font-size="9" fill="#475569">Dental office</text><rect x="36" y="168" width="114" height="60" rx="8" fill="#dbeafe" stroke="#cbd5e1"/><text x="93" y="192" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">11:30</text><text x="93" y="210" text-anchor="middle" font-size="9" fill="#475569">Bank branch</text><rect x="36" y="240" width="114" height="60" rx="8" fill="#dbeafe" stroke="#cbd5e1"/><text x="93" y="264" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">2:00</text><text x="93" y="282" text-anchor="middle" font-size="9" fill="#475569">School</text><rect x="166" y="56" width="130" height="270" rx="10" fill="#ffffff" stroke="#94a3b8"/><text x="231" y="80" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Crew B — Mike</text><rect x="174" y="96" width="114" height="60" rx="8" fill="#dcfce7" stroke="#cbd5e1"/><text x="231" y="120" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">9:00</text><text x="231" y="138" text-anchor="middle" font-size="9" fill="#475569">Insurance HQ</text><rect x="174" y="168" width="114" height="60" rx="8" fill="#dcfce7" stroke="#cbd5e1"/><text x="231" y="192" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">1:00</text><text x="231" y="210" text-anchor="middle" font-size="9" fill="#475569">Church hall</text><rect x="304" y="56" width="130" height="270" rx="10" fill="#ffffff" stroke="#94a3b8"/><text x="369" y="80" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Crew C — Ana</text><rect x="312" y="96" width="114" height="60" rx="8" fill="#fef9c3" stroke="#cbd5e1"/><text x="369" y="120" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">8:30</text><text x="369" y="138" text-anchor="middle" font-size="9" fill="#475569">Medical plaza</text><rect x="312" y="168" width="114" height="60" rx="8" fill="#fef9c3" stroke="#cbd5e1"/><text x="369" y="192" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">12:00</text><text x="369" y="210" text-anchor="middle" font-size="9" fill="#475569">Retail strip</text><text x="230" y="352" text-anchor="middle" font-size="12" fill="#475569">Every crew, every job, one screen. Gaps = lost money.</text></svg>';

-- quality-inspections: The inspection report: what the client actually sees
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'quality-inspections') and kind = 'visual' and title = 'The inspection report: what the client actually sees';
with c as (select id as cid from public.training_courses where slug = 'quality-inspections'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 2, 'visual', 'The inspection report: what the client actually sees',
'This is the report the client gets: one score out of 5, a bar for every area, and any problem flagged with a photo. Clients do not read paragraphs — they read the score. Anything under 4.0 triggers a re-clean the same day, and the photo proves what was found.',
'<svg width="460" height="402" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="392" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">INSPECTION REPORT</text><rect x="60" y="52" width="340" height="330" rx="6" fill="#ffffff" stroke="#94a3b8"/><text x="230" y="78" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">INSPECTION REPORT</text><text x="80" y="102" font-size="12" fill="#475569">Santos Insurance · Oct 1</text><text x="380" y="102" text-anchor="end" font-size="16" font-weight="bold" fill="#2563eb">4.2 / 5</text><line x1="80" y1="114" x2="380" y2="114" stroke="#e2e8f0"/><text x="80" y="140" font-size="12" fill="#0f172a">Lobby</text><rect x="180" y="128" width="140" height="14" rx="7" fill="#e2e8f0"/><rect x="180" y="128" width="126.0" height="14" rx="7" fill="#2563eb"/><text x="330" y="140" font-size="12" fill="#475569">4.5</text><text x="80" y="184" font-size="12" fill="#0f172a">Offices</text><rect x="180" y="172" width="140" height="14" rx="7" fill="#e2e8f0"/><rect x="180" y="172" width="112.0" height="14" rx="7" fill="#2563eb"/><text x="330" y="184" font-size="12" fill="#475569">4.0</text><text x="80" y="228" font-size="12" fill="#0f172a">Restrooms</text><rect x="180" y="216" width="140" height="14" rx="7" fill="#e2e8f0"/><rect x="180" y="216" width="84.0" height="14" rx="7" fill="#2563eb"/><text x="330" y="228" font-size="12" fill="#475569">3.0</text><text x="80" y="272" font-size="12" fill="#0f172a">Break room</text><rect x="180" y="260" width="140" height="14" rx="7" fill="#e2e8f0"/><rect x="180" y="260" width="119.0" height="14" rx="7" fill="#2563eb"/><text x="330" y="272" font-size="12" fill="#475569">4.2</text><text x="80" y="336" font-size="11" fill="#b45309">⚠ Restroom grout — photo attached</text><line x1="80" y1="356" x2="200" y2="356" stroke="#0f172a"/><text x="80" y="370" font-size="10" fill="#94a3b8">Inspector signature</text></svg>';

-- intro-commercial-cleaning: Dilution and dwell time: the two numbers that matter
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'intro-commercial-cleaning') and kind = 'visual' and title = 'Dilution and dwell time: the two numbers that matter';
with c as (select id as cid from public.training_courses where slug = 'intro-commercial-cleaning'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'Dilution and dwell time: the two numbers that matter',
'Two numbers decide whether your chemical works. Dilution: the label''s ratio is the law — 1:64 for glass, 1:32 for all-purpose, 1:10 for degreaser. More chemical does not clean better; it leaves sticky residue. Dwell time: spray and walk away for a full 10 minutes before wiping, or the disinfectant never finishes the job.',
'<svg width="460" height="332" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="322" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">DILUTION + DWELL TIME</text><rect x="40" y="56" width="180" height="220" rx="10" fill="#dbeafe" stroke="#2563eb"/><text x="130" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">DILUTION</text><text x="130" y="110" text-anchor="middle" font-size="12" fill="#1e3a8a">1 : 64  — glass</text><text x="130" y="136" text-anchor="middle" font-size="12" fill="#1e3a8a">1 : 32  — all-purpose</text><text x="130" y="162" text-anchor="middle" font-size="12" fill="#1e3a8a">1 : 10  — degreaser</text><text x="130" y="200" text-anchor="middle" font-size="11" fill="#1e3a8a">More chemical ≠ cleaner.</text><text x="130" y="218" text-anchor="middle" font-size="11" fill="#1e3a8a">It leaves residue.</text><rect x="240" y="56" width="180" height="220" rx="10" fill="#fef9c3" stroke="#ca8a04"/><text x="330" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#713f12">DWELL TIME</text><circle cx="330" cy="150" r="44" fill="#ffffff" stroke="#ca8a04" stroke-width="3"/><line x1="330" y1="150" x2="330" y2="118" stroke="#713f12" stroke-width="3"/><line x1="330" y1="150" x2="352" y2="160" stroke="#713f12" stroke-width="3"/><text x="330" y="220" text-anchor="middle" font-size="12" fill="#713f12">Spray. Wait 10 min.</text><text x="330" y="238" text-anchor="middle" font-size="12" fill="#713f12">Then wipe.</text><text x="230" y="310" text-anchor="middle" font-size="12" fill="#475569">Right mix + full dwell time = disinfection that actually works.</text></svg>';

-- medical-cleaning: Terminal clean: the six-zone room sequence
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'medical-cleaning') and kind = 'visual' and title = 'Terminal clean: the six-zone room sequence';
with c as (select id as cid from public.training_courses where slug = 'medical-cleaning'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'Terminal clean: the six-zone room sequence',
'A terminal clean moves in one direction through six zones: high dust first, then clean areas before dirty ones, top to bottom, trash and linen out, bathroom absolutely last, floor last of all. Never walk back through a zone you already cleaned — that is how germs travel.',
'<svg width="460" height="342" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="332" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">TERMINAL CLEAN SEQUENCE</text><rect x="40" y="56" width="380" height="230" rx="10" fill="#ffffff" stroke="#94a3b8"/><circle cx="60" cy="70" r="20" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="60" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#7f1d1d">1</text><text x="60" y="108" text-anchor="middle" font-size="10" fill="#475569">High dust</text><circle cx="200" cy="70" r="20" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="200" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#7f1d1d">2</text><text x="200" y="108" text-anchor="middle" font-size="10" fill="#475569">Clean to dirty</text><circle cx="330" cy="70" r="20" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="330" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#7f1d1d">3</text><text x="330" y="108" text-anchor="middle" font-size="10" fill="#475569">Bathroom LAST</text><circle cx="60" cy="200" r="20" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="60" y="206" text-anchor="middle" font-size="14" font-weight="bold" fill="#7f1d1d">4</text><text x="60" y="238" text-anchor="middle" font-size="10" fill="#475569">Top to bottom</text><circle cx="200" cy="200" r="20" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="200" y="206" text-anchor="middle" font-size="14" font-weight="bold" fill="#7f1d1d">5</text><text x="200" y="238" text-anchor="middle" font-size="10" fill="#475569">Trash + linen</text><circle cx="330" cy="200" r="20" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="330" y="206" text-anchor="middle" font-size="14" font-weight="bold" fill="#7f1d1d">6</text><text x="330" y="238" text-anchor="middle" font-size="10" fill="#475569">Floor last</text><text x="230" y="320" text-anchor="middle" font-size="12" fill="#475569">One direction only. Never go back over a clean zone.</text></svg>';

-- residential-cleaning: The final walk: seeing it through the homeowner's eyes
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'residential-cleaning') and kind = 'visual' and title = 'The final walk: seeing it through the homeowner''s eyes';
with c as (select id as cid from public.training_courses where slug = 'residential-cleaning'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'The final walk: seeing it through the homeowner''s eyes',
'Before you leave, walk the home the way the homeowner will: slowly, eyes up. Lights, mirrors, floor edges, trash, behind the toilets, doors locked and alarm set. The final walk catches the one thing that would have become a complaint text at 9 PM.',
'<svg width="460" height="372" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="362" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">FINAL WALK CHECKLIST</text><rect x="60" y="56" width="340" height="30" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="68" y="62" width="18" height="18" rx="5" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/><text x="77" y="76" text-anchor="middle" font-size="13" font-weight="bold" fill="#cbd5e1"></text><text x="94" y="76" font-size="12" fill="#0f172a">All lights on, then off at the end</text><rect x="60" y="100" width="340" height="30" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="68" y="106" width="18" height="18" rx="5" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/><text x="77" y="120" text-anchor="middle" font-size="13" font-weight="bold" fill="#cbd5e1"></text><text x="94" y="120" font-size="12" fill="#0f172a">Mirrors: no streaks, no drips</text><rect x="60" y="144" width="340" height="30" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="68" y="150" width="18" height="18" rx="5" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/><text x="77" y="164" text-anchor="middle" font-size="13" font-weight="bold" fill="#cbd5e1"></text><text x="94" y="164" font-size="12" fill="#0f172a">Floors: edges and corners, not just centers</text><rect x="60" y="188" width="340" height="30" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="68" y="194" width="18" height="18" rx="5" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/><text x="77" y="208" text-anchor="middle" font-size="13" font-weight="bold" fill="#cbd5e1"></text><text x="94" y="208" font-size="12" fill="#0f172a">Trash out, fresh liners in</text><rect x="60" y="232" width="340" height="30" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="68" y="238" width="18" height="18" rx="5" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/><text x="77" y="252" text-anchor="middle" font-size="13" font-weight="bold" fill="#cbd5e1"></text><text x="94" y="252" font-size="12" fill="#0f172a">Toilets: base and behind, not just the bowl</text><rect x="60" y="276" width="340" height="30" rx="8" fill="#ffffff" stroke="#cbd5e1"/><rect x="68" y="282" width="18" height="18" rx="5" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/><text x="77" y="296" text-anchor="middle" font-size="13" font-weight="bold" fill="#cbd5e1"></text><text x="94" y="296" font-size="12" fill="#0f172a">Doors locked, alarm set</text><text x="230" y="352" text-anchor="middle" font-size="12" fill="#475569">Walk it like the homeowner — slow, eyes up.</text></svg>';

-- move-in-move-out: The 48-hour turn: beat the clock
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'move-in-move-out') and kind = 'visual' and title = 'The 48-hour turn: beat the clock';
with c as (select id as cid from public.training_courses where slug = 'move-in-move-out'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'The 48-hour turn: beat the clock',
'A unit turn runs on a 48-hour clock: keys at hour zero, rough clean by hour 4, full detail by hour 24, final walk at hour 44, handoff at 48. There are no extensions — the new tenant is standing at the door. If you fall behind at hour 4, call for help then, not at hour 40.',
'<svg width="460" height="272" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="262" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">48-HOUR TURN TIMELINE</text><line x1="30" y1="150" x2="430" y2="150" stroke="#94a3b8" stroke-width="3"/><circle cx="60" cy="150" r="13" fill="#dbeafe" stroke="#475569" stroke-width="2"/><text x="60" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">HR 0</text><text x="60" y="200" text-anchor="middle" font-size="9" fill="#475569">Keys in hand</text><circle cx="146" cy="150" r="13" fill="#e0f2fe" stroke="#475569" stroke-width="2"/><text x="146" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">HR 4</text><text x="146" y="200" text-anchor="middle" font-size="9" fill="#475569">Rough clean done</text><circle cx="232" cy="150" r="13" fill="#fef9c3" stroke="#475569" stroke-width="2"/><text x="232" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">HR 24</text><text x="232" y="200" text-anchor="middle" font-size="9" fill="#475569">Detail clean done</text><circle cx="318" cy="150" r="13" fill="#ffedd5" stroke="#475569" stroke-width="2"/><text x="318" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">HR 44</text><text x="318" y="200" text-anchor="middle" font-size="9" fill="#475569">Final walk</text><circle cx="404" cy="150" r="13" fill="#dcfce7" stroke="#475569" stroke-width="2"/><text x="404" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">HR 48</text><text x="404" y="200" text-anchor="middle" font-size="9" fill="#475569">Handoff</text><text x="230" y="250" text-anchor="middle" font-size="12" fill="#475569">48 hours. No extensions — the new tenant arrives.</text></svg>';

-- new-construction-cleaning: Rough clean vs. final clean: know which one you're doing
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'new-construction-cleaning') and kind = 'visual' and title = 'Rough clean vs. final clean: know which one you''re doing';
with c as (select id as cid from public.training_courses where slug = 'new-construction-cleaning'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'Rough clean vs. final clean: know which one you''re doing',
'Rough and final are different jobs with different standards. Rough clean: debris and stickers off, dry dust, scrape paint off windows — trades are still working, so do not mop. Final clean: detail every surface, wet-wipe and polish, squeegee the glass, finish the floors — a homeowner walks in after you.',
'<svg width="460" height="362" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="352" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">ROUGH VS FINAL CLEAN</text><rect x="30" y="56" width="195" height="250" rx="10" fill="#e0f2fe" stroke="#0284c7"/><text x="127" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#0c4a6e">ROUGH CLEAN</text><text x="127" y="108" text-anchor="middle" font-size="11" fill="#0c4a6e">Debris + stickers off</text><text x="127" y="130" text-anchor="middle" font-size="11" fill="#0c4a6e">Dry dust everything</text><text x="127" y="152" text-anchor="middle" font-size="11" fill="#0c4a6e">Windows: scrape paint</text><text x="127" y="174" text-anchor="middle" font-size="11" fill="#0c4a6e">No mopping yet</text><text x="127" y="196" text-anchor="middle" font-size="11" fill="#0c4a6e">Trades still working</text><rect x="235" y="56" width="195" height="250" rx="10" fill="#dcfce7" stroke="#16a34a"/><text x="332" y="82" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">FINAL CLEAN</text><text x="332" y="108" text-anchor="middle" font-size="11" fill="#14532d">Detail every surface</text><text x="332" y="130" text-anchor="middle" font-size="11" fill="#14532d">Wet-wipe + polish</text><text x="332" y="152" text-anchor="middle" font-size="11" fill="#14532d">Windows: squeegee shine</text><text x="332" y="174" text-anchor="middle" font-size="11" fill="#14532d">Floors: mop + finish</text><text x="332" y="196" text-anchor="middle" font-size="11" fill="#14532d">Move-in ready</text><text x="230" y="340" text-anchor="middle" font-size="12" fill="#475569">Rough = construction zone. Final = homeowner walks in.</text></svg>';

-- floor-care: Finish problems: see it, name it, fix it
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'floor-care') and kind = 'visual' and title = 'Finish problems: see it, name it, fix it';
with c as (select id as cid from public.training_courses where slug = 'floor-care'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'Finish problems: see it, name it, fix it',
'Three finish problems cover 90% of callbacks. Yellowing means too many coats — strip and recoat. Peeling means poor prep or wet mopping — strip, prep properly, recoat. Dull traffic lanes mean worn finish — scrub and recoat just the lanes. Name it right and the fix is obvious.',
'<svg width="460" height="344" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="334" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">FINISH TROUBLESHOOTING</text><rect x="30" y="52" width="400" height="30" rx="8" fill="#0f172a"/><text x="80" y="72" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">YOU SEE</text><text x="230" y="72" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">CAUSE</text><text x="360" y="72" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">FIX</text><rect x="30" y="92" width="400" height="60" rx="8" fill="#ffffff" stroke="#cbd5e1"/><text x="80" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">Yellowing</text><text x="230" y="128" text-anchor="middle" font-size="12" fill="#475569">Too many coats</text><text x="360" y="128" text-anchor="middle" font-size="12" fill="#14532d">Strip and recoat</text><rect x="30" y="162" width="400" height="60" rx="8" fill="#ffffff" stroke="#cbd5e1"/><text x="80" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">Peeling</text><text x="230" y="198" text-anchor="middle" font-size="12" fill="#475569">Poor prep / wet mop</text><text x="360" y="198" text-anchor="middle" font-size="12" fill="#14532d">Strip, prep, recoat</text><rect x="30" y="232" width="400" height="60" rx="8" fill="#ffffff" stroke="#cbd5e1"/><text x="80" y="268" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">Dull traffic lanes</text><text x="230" y="268" text-anchor="middle" font-size="12" fill="#475569">Worn finish</text><text x="360" y="268" text-anchor="middle" font-size="12" fill="#14532d">Scrub and recoat</text><text x="230" y="322" text-anchor="middle" font-size="12" fill="#475569">Name it right and the fix is obvious.</text></svg>';

-- carpet-cleaning: Spot treatment quick chart: match the spot to the fix
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'carpet-cleaning') and kind = 'visual' and title = 'Spot treatment quick chart: match the spot to the fix';
with c as (select id as cid from public.training_courses where slug = 'carpet-cleaning'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'Spot treatment quick chart: match the spot to the fix',
'The wrong chemical sets a stain forever, so match first, treat second. Coffee and tea want tannin spotter. Grease and oil want dry solvent. Ink wants isopropyl alcohol. Gum wants freezing, then scraping. Blot — never rub — and always test in a closet corner first.',
'<svg width="460" height="370" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="360" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">SPOT TREATMENT CHART</text><rect x="40" y="56" width="180" height="56" rx="8" fill="#fee2e2" stroke="#dc2626"/><text x="130" y="90" text-anchor="middle" font-size="13" font-weight="bold" fill="#7f1d1d">Coffee / tea</text><text x="245" y="90" text-anchor="middle" font-size="16" fill="#64748b">→</text><rect x="270" y="56" width="150" height="56" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="345" y="90" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Tannin spotter</text><rect x="40" y="124" width="180" height="56" rx="8" fill="#fee2e2" stroke="#dc2626"/><text x="130" y="158" text-anchor="middle" font-size="13" font-weight="bold" fill="#7f1d1d">Grease / oil</text><text x="245" y="158" text-anchor="middle" font-size="16" fill="#64748b">→</text><rect x="270" y="124" width="150" height="56" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="345" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Dry solvent</text><rect x="40" y="192" width="180" height="56" rx="8" fill="#fee2e2" stroke="#dc2626"/><text x="130" y="226" text-anchor="middle" font-size="13" font-weight="bold" fill="#7f1d1d">Ink</text><text x="245" y="226" text-anchor="middle" font-size="16" fill="#64748b">→</text><rect x="270" y="192" width="150" height="56" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="345" y="226" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Isopropyl alcohol</text><rect x="40" y="260" width="180" height="56" rx="8" fill="#fee2e2" stroke="#dc2626"/><text x="130" y="294" text-anchor="middle" font-size="13" font-weight="bold" fill="#7f1d1d">Gum</text><text x="245" y="294" text-anchor="middle" font-size="16" fill="#64748b">→</text><rect x="270" y="260" width="150" height="56" rx="8" fill="#dcfce7" stroke="#16a34a"/><text x="345" y="294" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Freeze + scrape</text><text x="230" y="348" text-anchor="middle" font-size="12" fill="#475569">Wrong chemical sets the stain forever. Match first.</text></svg>';

-- window-cleaning: Ladder setup: the 4-to-1 rule and the safety check
delete from public.training_lessons where course_id = (select id from public.training_courses where slug = 'window-cleaning') and kind = 'visual' and title = 'Ladder setup: the 4-to-1 rule and the safety check';
with c as (select id as cid from public.training_courses where slug = 'window-cleaning'),
st as (select step_number, id as sid from public.training_steps where course_id = (select cid from c))
insert into public.training_lessons (course_id, step_id, sort_order, kind, title, body, media_svg)
select (select cid from c), (select sid from st where step_number = 2), 3, 'visual', 'Ladder setup: the 4-to-1 rule and the safety check',
'For every 4 feet of height, the ladder base sits 1 foot out from the wall. Keep three points of contact — two hands and a foot, or two feet and a hand — at all times. Before climbing: extension locks engaged, feet on solid level ground, and never stand on the top three rungs.',
'<svg width="460" height="480" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="5" width="450" height="470" rx="12" fill="#f8fafc" stroke="#cbd5e1"/><text x="230" y="32" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">LADDER SAFETY</text><text x="230" y="70" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">THE 4-TO-1 RULE</text><line x1="120" y1="280" x2="200" y2="100" stroke="#b45309" stroke-width="8"/><line x1="280" y1="280" x2="200" y2="100" stroke="#b45309" stroke-width="8"/><line x1="120" y1="280" x2="280" y2="280" stroke="#94a3b8" stroke-width="2" stroke-dasharray="6,4"/><text x="200" y="300" text-anchor="middle" font-size="12" fill="#475569">4 ft up = 1 ft out</text><text x="200" y="322" text-anchor="middle" font-size="12" fill="#475569">3 points of contact, always</text><rect x="90" y="336" width="280" height="30" rx="8" fill="#dcfce7" stroke="#16a34a"/><rect x="98" y="342" width="18" height="18" rx="5" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><text x="107" y="356" text-anchor="middle" font-size="13" font-weight="bold" fill="#16a34a">✓</text><text x="124" y="356" font-size="12" fill="#0f172a">Extension locks engaged</text><rect x="90" y="376" width="280" height="30" rx="8" fill="#dcfce7" stroke="#16a34a"/><rect x="98" y="382" width="18" height="18" rx="5" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><text x="107" y="396" text-anchor="middle" font-size="13" font-weight="bold" fill="#16a34a">✓</text><text x="124" y="396" font-size="12" fill="#0f172a">Feet on solid, level ground</text><rect x="90" y="416" width="280" height="30" rx="8" fill="#dcfce7" stroke="#16a34a"/><rect x="98" y="422" width="18" height="18" rx="5" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><text x="107" y="436" text-anchor="middle" font-size="13" font-weight="bold" fill="#16a34a">✓</text><text x="124" y="436" font-size="12" fill="#0f172a">Top 3 rungs off-limits</text></svg>';
